from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    groups = []  # Initialize list to store separated groups

    stack = []  # Stack to keep track of opening parentheses
    start = 0  # Index to keep track of the start of a group

    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            start = stack.pop()  # Extract the start index of the group
            groups.append(paren_string[start:i+1])  # Extract the group and add to the list

    return groups  # Return the list of separated groups
